<?php
require_once __DIR__.'/../includes/bootstrap.php';
require_role('commercial_manager');
$user=current_user();$flashes=render_flashes();
require_once __DIR__.'/_helpers.php';
$conn=Database::getConnection();$managerId=(int)($user['id']??$user['user_id']??0);
if($managerId<1){http_response_code(403);exit('Invalid Commercial Manager account.');}
$currentPage='risk_compliance';$pageTitle='Risk & Compliance Monitoring';
function rc_e($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
function rc_date(string $v,bool $optional=false):bool{if($optional&&$v==='')return true;$d=DateTime::createFromFormat('Y-m-d',$v);return $d&&$d->format('Y-m-d')===$v;}
function rc_redirect():never{header('Location: '.url('commercial_manager/risk_compliance.php'));exit;}
$tables=['commercial_risks','commercial_compliance_obligations'];$missing=[];foreach($tables as $t)if(!cm_table($conn,$t))$missing[]=$t;
if($missing){require __DIR__.'/_layout_start.php';?><div class="rc-panel">Import <b>commercial_risk_compliance_migration.sql</b> and reload this page.</div><?php require __DIR__.'/_layout_end.php';exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 cm_verify_csrf();$action=(string)($_POST['action']??'');
 try{
 if($action==='create_risk'){
  $title=trim((string)($_POST['title']??''));$cat=(string)($_POST['category']??'operational');$rel=(string)($_POST['related_type']??'general');$rid=max(0,(int)($_POST['related_id']??0));$sev=(string)($_POST['severity']??'medium');$l=(int)($_POST['likelihood']??3);$i=(int)($_POST['impact']??3);$owner=trim((string)($_POST['risk_owner']??''));$desc=trim((string)($_POST['description']??''));$plan=trim((string)($_POST['mitigation_plan']??''));$review=trim((string)($_POST['review_date']??''));
  if($title===''||!in_array($cat,['financial','legal','operational','reputational','delivery','relationship','regulatory','other'],true)||!in_array($rel,['general','client','proposal','contract'],true)||!in_array($sev,['low','medium','high','critical'],true)||$l<1||$l>5||$i<1||$i>5||!rc_date($review,true))throw new RuntimeException('Complete the risk title and valid assessment details.');
  $score=$l*$i;$q=$conn->prepare("INSERT INTO commercial_risks(commercial_manager_id,title,category,related_type,related_id,severity,likelihood,impact,risk_score,risk_owner,description,mitigation_plan,review_date,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,NULLIF(?,''),'open')");
  $q->bind_param('isssisiiissss',$managerId,$title,$cat,$rel,$rid,$sev,$l,$i,$score,$owner,$desc,$plan,$review);if(!$q->execute())throw new RuntimeException('Risk could not be saved.');$id=(int)$q->insert_id;$q->close();cm_activity($conn,$managerId,'commercial_risk_created','Created risk: '.$title,'commercial_risk',$id);cm_flash('success','Commercial risk added.');
 }elseif($action==='update_risk'){
  $id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'open');$sev=(string)($_POST['severity']??'medium');$l=(int)($_POST['likelihood']??3);$i=(int)($_POST['impact']??3);$owner=trim((string)($_POST['risk_owner']??''));$plan=trim((string)($_POST['mitigation_plan']??''));$review=trim((string)($_POST['review_date']??''));
  if(!in_array($status,['open','mitigating','monitoring','closed','accepted'],true)||!in_array($sev,['low','medium','high','critical'],true)||$l<1||$l>5||$i<1||$i>5||!rc_date($review,true))throw new RuntimeException('Invalid risk update.');
  $score=$l*$i;$q=$conn->prepare("UPDATE commercial_risks SET status=?,severity=?,likelihood=?,impact=?,risk_score=?,risk_owner=?,mitigation_plan=?,review_date=NULLIF(?, '') WHERE id=? AND commercial_manager_id=?");$q->bind_param('ssiiisssii',$status,$sev,$l,$i,$score,$owner,$plan,$review,$id,$managerId);$q->execute();$q->close();cm_activity($conn,$managerId,'commercial_risk_updated','Updated risk #'.$id,'commercial_risk',$id);cm_flash('success','Risk assessment updated.');
 }elseif($action==='create_obligation'){
  $title=trim((string)($_POST['obligation_title']??''));$contract=trim((string)($_POST['contract_reference']??''));$clause=trim((string)($_POST['clause_reference']??''));$owner=trim((string)($_POST['responsible_owner']??''));$due=trim((string)($_POST['due_date']??''));$freq=(string)($_POST['frequency']??'once');$status=(string)($_POST['compliance_status']??'pending');$evidence=trim((string)($_POST['evidence_notes']??''));
  if($title===''||$contract===''||!rc_date($due)||!in_array($freq,['once','monthly','quarterly','annually'],true)||!in_array($status,['pending','in_progress','compliant','at_risk','breached','waived'],true))throw new RuntimeException('Enter an obligation, contract reference and valid due date.');
  $q=$conn->prepare('INSERT INTO commercial_compliance_obligations(commercial_manager_id,obligation_title,contract_reference,clause_reference,responsible_owner,due_date,frequency,compliance_status,evidence_notes) VALUES(?,?,?,?,?,?,?,?,?)');$q->bind_param('issssssss',$managerId,$title,$contract,$clause,$owner,$due,$freq,$status,$evidence);if(!$q->execute())throw new RuntimeException('Obligation could not be saved.');$id=(int)$q->insert_id;$q->close();cm_activity($conn,$managerId,'compliance_obligation_created','Created obligation: '.$title,'compliance_obligation',$id);cm_flash('success','Contractual obligation recorded.');
 }elseif($action==='update_obligation'){
  $id=(int)($_POST['id']??0);$status=(string)($_POST['compliance_status']??'pending');$owner=trim((string)($_POST['responsible_owner']??''));$due=trim((string)($_POST['due_date']??''));$evidence=trim((string)($_POST['evidence_notes']??''));if(!in_array($status,['pending','in_progress','compliant','at_risk','breached','waived'],true)||!rc_date($due))throw new RuntimeException('Invalid compliance update.');
  $q=$conn->prepare("UPDATE commercial_compliance_obligations SET compliance_status=?,responsible_owner=?,due_date=?,evidence_notes=?,completed_at=CASE WHEN ?='compliant' THEN NOW() ELSE NULL END WHERE id=? AND commercial_manager_id=?");$q->bind_param('sssssii',$status,$owner,$due,$evidence,$status,$id,$managerId);$q->execute();$q->close();cm_activity($conn,$managerId,'compliance_obligation_updated','Updated obligation #'.$id.' to '.$status,'compliance_obligation',$id);cm_flash('success','Compliance obligation updated.');
 }else throw new RuntimeException('Unsupported action.');
 }catch(Throwable $e){cm_flash('error',$e->getMessage());}rc_redirect();
}
$q=$conn->prepare('SELECT * FROM commercial_risks WHERE commercial_manager_id=? ORDER BY FIELD(severity,"critical","high","medium","low"),risk_score DESC,created_at DESC');$q->bind_param('i',$managerId);$q->execute();$risks=$q->get_result()->fetch_all(MYSQLI_ASSOC);$q->close();
$q=$conn->prepare('SELECT * FROM commercial_compliance_obligations WHERE commercial_manager_id=? ORDER BY due_date');$q->bind_param('i',$managerId);$q->execute();$obligations=$q->get_result()->fetch_all(MYSQLI_ASSOC);$q->close();
$today=date('Y-m-d');$open=0;$high=0;$overdue=0;$breached=0;$dueSoon=0;foreach($risks as $r){if(!in_array($r['status'],['closed','accepted'],true)){$open++;if(in_array($r['severity'],['high','critical'],true))$high++;}}foreach($obligations as $o){$active=!in_array($o['compliance_status'],['compliant','waived'],true);if($o['compliance_status']==='breached')$breached++;if($active&&$o['due_date']<$today)$overdue++;if($active&&$o['due_date']>=$today&&$o['due_date']<=date('Y-m-d',strtotime('+30 days')))$dueSoon++;}
require __DIR__.'/_layout_start.php';
?>
<style>
.rc-head{margin:8px 0 18px}.rc-head h2{font-size:25px;margin:4px 0}.rc-muted{color:var(--muted);font-size:12px}.rc-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:16px 0}.rc-stat,.rc-panel{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px;min-width:0}.rc-stat span{display:block;color:var(--muted);font-size:12px}.rc-stat strong{display:block;font-size:24px;margin-top:6px}.rc-panel{margin:15px 0}.rc-panel h3{font-size:17px;margin:0 0 13px}.rc-form{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px;align-items:end}.rc-field label{display:block;font-size:12px;font-weight:700;margin-bottom:5px}.rc-field input,.rc-field select,.rc-field textarea{width:100%;padding:9px;border:1px solid var(--line);border-radius:8px;background:var(--surface);color:var(--text);font:inherit}.rc-field textarea{min-height:65px}.rc-wide{grid-column:span 2}.rc-btn{background:var(--primary);color:#fff;border:0;border-radius:8px;padding:10px 13px;font-weight:700;cursor:pointer}.rc-tablewrap{overflow:auto}.rc-table{width:100%;min-width:850px;border-collapse:collapse}.rc-table th,.rc-table td{padding:10px;border-bottom:1px solid var(--line);text-align:left;font-size:12px;vertical-align:top}.rc-table th{color:var(--muted);font-size:10px;text-transform:uppercase}.rc-tag{display:inline-block;padding:4px 8px;border-radius:20px;background:var(--surface2);font-size:10px;font-weight:700}.rc-danger{color:#b42318}.rc-warn{color:#a15c00}@media(max-width:950px){.rc-stats{grid-template-columns:repeat(2,1fr)}.rc-form{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){.rc-stats,.rc-form{grid-template-columns:1fr}.rc-wide{grid-column:auto}}
</style>
