<div class="rc-stats"><div class="rc-stat"><span>Open risks</span><strong><?=$open?></strong><small class="rc-muted"><?=count($risks)?> recorded</small></div><div class="rc-stat"><span>High / critical risks</span><strong><?=$high?></strong></div><div class="rc-stat"><span>Overdue obligations</span><strong><?=$overdue?></strong></div><div class="rc-stat"><span>Breaches / due in 30 days</span><strong><?=$breached?> / <?=$dueSoon?></strong></div></div>
<section class="rc-panel"><h3>Register a commercial risk</h3><form method="post" class="rc-form"><input type="hidden" name="csrf_token" value="<?=rc_e(cm_csrf())?>"><input type="hidden" name="action" value="create_risk">
<div class="rc-field rc-wide"><label>Risk title</label><input name="title" required maxlength="180"></div><div class="rc-field"><label>Category</label><select name="category"><?php foreach(['financial','legal','operational','reputational','delivery','relationship','regulatory','other'] as $v):?><option><?=$v?></option><?php endforeach;?></select></div><div class="rc-field"><label>Related record</label><select name="related_type"><option value="general">General</option><option value="client">Client account</option><option value="proposal">Proposal</option><option value="contract">Contract</option></select></div><div class="rc-field"><label>Related record ID</label><input type="number" min="0" name="related_id" value="0"></div><div class="rc-field"><label>Severity</label><select name="severity"><?php foreach(['low','medium','high','critical'] as $v):?><option <?=$v==='medium'?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="rc-field"><label>Likelihood (1–5)</label><input type="number" min="1" max="5" name="likelihood" value="3"></div><div class="rc-field"><label>Impact (1–5)</label><input type="number" min="1" max="5" name="impact" value="3"></div><div class="rc-field"><label>Risk owner</label><input name="risk_owner"></div><div class="rc-field"><label>Next review</label><input type="date" name="review_date"></div><div class="rc-field rc-wide"><label>Description / consequence</label><textarea name="description"></textarea></div><div class="rc-field rc-wide"><label>Mitigation plan</label><textarea name="mitigation_plan"></textarea></div><button class="rc-btn">Add risk</button></form></section>
<section class="rc-panel"><h3>Commercial risk register</h3><div class="rc-tablewrap"><table class="rc-table"><thead><tr><th>Risk</th><th>Category / link</th><th>Assessment</th><th>Owner / review</th><th>Mitigation / status</th><th>Update</th></tr></thead><tbody><?php foreach($risks as $r):?><tr><td><b><?=rc_e($r['title'])?></b><div class="rc-muted"><?=rc_e($r['description'])?></div></td><td><?=rc_e($r['category'])?><div class="rc-muted"><?=rc_e($r['related_type'])?> #<?=$r['related_id']?></div></td><td><span class="rc-tag <?=in_array($r['severity'],['high','critical'],true)?'rc-danger':''?>"><?=strtoupper(rc_e($r['severity']))?></span><div class="rc-muted">L <?=$r['likelihood']?> × I <?=$r['impact']?> = <?=$r['risk_score']?></div></td><td><?=rc_e($r['risk_owner']?:'Unassigned')?><div class="rc-muted"><?=rc_e($r['review_date']?:'No review date')?></div></td><td><?=rc_e($r['mitigation_plan'])?><div><span class="rc-tag"><?=rc_e($r['status'])?></span></div></td><td><details><summary>Update</summary><form method="post" class="rc-form" style="grid-template-columns:1fr;margin-top:8px"><input type="hidden" name="csrf_token" value="<?=rc_e(cm_csrf())?>"><input type="hidden" name="action" value="update_risk"><input type="hidden" name="id" value="<?=$r['id']?>"><div class="rc-field"><label>Status</label><select name="status"><?php foreach(['open','mitigating','monitoring','accepted','closed'] as $v):?><option value="<?=$v?>" <?=$r['status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="rc-field"><label>Severity</label><select name="severity"><?php foreach(['low','medium','high','critical'] as $v):?><option value="<?=$v?>" <?=$r['severity']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="rc-field"><label>Likelihood / impact (1–5)</label><input type="number" name="likelihood" min="1" max="5" value="<?=$r['likelihood']?>"><input type="number" name="impact" min="1" max="5" value="<?=$r['impact']?>"></div><div class="rc-field"><label>Owner</label><input name="risk_owner" value="<?=rc_e($r['risk_owner'])?>"></div><div class="rc-field"><label>Review date</label><input type="date" name="review_date" value="<?=rc_e($r['review_date'])?>"></div><div class="rc-field"><label>Mitigation</label><textarea name="mitigation_plan"><?=rc_e($r['mitigation_plan'])?></textarea></div><button class="rc-btn">Save update</button></form></details></td></tr><?php endforeach;?><?php if(!$risks):?><tr><td colspan="6">No risks recorded.</td></tr><?php endif;?></tbody></table></div></section>
<section class="rc-panel"><h3>Record contractual obligation</h3><form method="post" class="rc-form"><input type="hidden" name="csrf_token" value="<?=rc_e(cm_csrf())?>"><input type="hidden" name="action" value="create_obligation"><div class="rc-field rc-wide"><label>Obligation / requirement</label><input name="obligation_title" required></div><div class="rc-field"><label>Contract reference</label><input name="contract_reference" required></div><div class="rc-field"><label>Clause reference</label><input name="clause_reference"></div><div class="rc-field"><label>Responsible owner</label><input name="responsible_owner"></div><div class="rc-field"><label>Due date</label><input type="date" name="due_date" required></div><div class="rc-field"><label>Frequency</label><select name="frequency"><option value="once">Once-off</option><option value="monthly">Monthly</option><option value="quarterly">Quarterly</option><option value="annually">Annually</option></select></div><div class="rc-field"><label>Status</label><select name="compliance_status"><?php foreach(['pending','in_progress','at_risk','breached','compliant','waived'] as $v):?><option value="<?=$v?>"><?=ucwords(str_replace('_',' ',$v))?></option><?php endforeach;?></select></div><div class="rc-field rc-wide"><label>Evidence / notes</label><textarea name="evidence_notes"></textarea></div><button class="rc-btn">Add obligation</button></form></section>
<section class="rc-panel"><h3>Contract compliance tracker</h3><div class="rc-tablewrap"><table class="rc-table"><thead><tr><th>Obligation / clause</th><th>Contract</th><th>Owner</th><th>Due</th><th>Status / alert</th><th>Update</th></tr></thead><tbody><?php foreach($obligations as $o):$late=!in_array($o['compliance_status'],['compliant','waived'],true)&&$o['due_date']<$today;$soon=!$late&&!in_array($o['compliance_status'],['compliant','waived'],true)&&$o['due_date']<=date('Y-m-d',strtotime('+30 days'));?><tr><td><b><?=rc_e($o['obligation_title'])?></b><div class="rc-muted">Clause <?=rc_e($o['clause_reference']?:'—')?> · <?=rc_e($o['frequency'])?></div><div class="rc-muted"><?=rc_e($o['evidence_notes'])?></div></td><td><?=rc_e($o['contract_reference'])?></td><td><?=rc_e($o['responsible_owner']?:'Unassigned')?></td><td><?=rc_e($o['due_date'])?></td><td><span class="rc-tag <?=($late||$o['compliance_status']==='breached')?'rc-danger':($soon||$o['compliance_status']==='at_risk'?'rc-warn':'')?>"><?=rc_e($o['compliance_status'])?></span><?php if($late):?><div class="rc-muted">OVERDUE</div><?php elseif($soon):?><div class="rc-muted">Due within 30 days</div><?php endif;?></td><td><details><summary>Update</summary><form method="post" class="rc-form" style="grid-template-columns:1fr;margin-top:8px"><input type="hidden" name="csrf_token" value="<?=rc_e(cm_csrf())?>"><input type="hidden" name="action" value="update_obligation"><input type="hidden" name="id" value="<?=$o['id']?>"><div class="rc-field"><label>Status</label><select name="compliance_status"><?php foreach(['pending','in_progress','compliant','at_risk','breached','waived'] as $v):?><option value="<?=$v?>" <?=$o['compliance_status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="rc-field"><label>Owner</label><input name="responsible_owner" value="<?=rc_e($o['responsible_owner'])?>"></div><div class="rc-field"><label>Due date</label><input type="date" name="due_date" value="<?=rc_e($o['due_date'])?>" required></div><div class="rc-field"><label>Evidence / notes</label><textarea name="evidence_notes"><?=rc_e($o['evidence_notes'])?></textarea></div><button class="rc-btn">Save compliance update</button></form></details></td></tr><?php endforeach;?><?php if(!$obligations):?><tr><td colspan="6">No obligations recorded.</td></tr><?php endif;?></tbody></table></div></section>
